const MIN_RENDER_INTERVAL: Duration = Duration::from_millis(16);

/// `PIR_DEBUG_REDRAW` (ADR-0001 rename of `PI_DEBUG_REDRAW`, tui.ts:1331).
const ENV_DEBUG_REDRAW: &str = "PIR_DEBUG_REDRAW";
