    fn composite_overlays(
        &self,
        lines: Vec<String>,
        term_width: i32,
        term_height: i32,
    ) -> Vec<String> {
        if self.overlay_stack.is_empty() {
            return lines;
        }
        let mut result = lines;

        // Pre-render all visible overlays and calculate positions.
